package com.godjiismp.mixin;
import com.godjiismp.skills.Skills;import com.godjiismp.skills.SkillsConfig;import net.minecraft.server.level.ServerPlayer;import net.minecraft.world.entity.player.Player;import net.minecraft.world.level.block.state.BlockState;import org.spongepowered.asm.mixin.Mixin;import org.spongepowered.asm.mixin.injection.At;import org.spongepowered.asm.mixin.injection.Inject;import org.spongepowered.asm.mixin.injection.callback.CallbackInfoReturnable;
@Mixin(Player.class) public abstract class SkillMiningMixin {@Inject(method="getDestroySpeed",at=@At("RETURN"),cancellable=true) private void godjiismp$increaseMiningSpeed(BlockState state,CallbackInfoReturnable<Float> cir){Player player=(Player)(Object)this;if(player instanceof ServerPlayer serverPlayer)cir.setReturnValue(cir.getReturnValue()*(1.0f+(float)(Skills.level(serverPlayer,2)*SkillsConfig.miningPerLevel)));}}
